int handle_far_return(struct x86_emulate_ctxt *ctxt) {
    uint64_t eip, cs;

    if (emulate_pop(ctxt, &eip) != X86EMUL_CONTINUE)
        return X86EMUL_UNHANDLEABLE;

    if (emulate_pop(ctxt, &cs) != X86EMUL_CONTINUE)
        return X86EMUL_UNHANDLEABLE;

    if (check_segment_privilege(ctxt, cs))
        return X86EMUL_PRIVILEGE;

    if (load_code_segment(ctxt, cs) != X86EMUL_CONTINUE)
        return X86EMUL_UNHANDLEABLE;

    ctxt->eip = eip;
    return X86EMUL_CONTINUE;
}

int handle_far_return(struct x86_emulate_ctxt *ctxt) {
    uint64_t eip, cs;
    int rc;

    rc = emulate_pop(ctxt, &eip);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    rc = emulate_pop(ctxt, &cs);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    if (!ctxt->ops->set_segment_register(ctxt, SEGMENT_CS, cs, 0, NULL)) {
        return X86EMUL_UNHANDLEABLE;
    }

    ctxt->eip = eip;

    return X86EMUL_CONTINUE;
}

int handle_far_return(struct x86_emulate_ctxt *ctxt) {
    uint64_t eip;
    uint16_t cs;

    if (emulate_pop(ctxt, &eip))
        return X86EMUL_UNHANDLEABLE;

    if (emulate_pop(ctxt, &cs))
        return X86EMUL_UNHANDLEABLE;

    if (!ctxt->ops->get_segment(ctxt, &cs)) {
        return X86EMUL_UNHANDLEABLE;
    }

    ctxt->eip = eip;
    return X86EMUL_CONTINUE;
}

int handle_far_return(struct x86_emulate_ctxt *ctxt) {
    uint64_t eip;
    uint16_t cs;

    if (emulate_pop(ctxt, &eip) != X86EMUL_CONTINUE)
        return X86EMUL_UNHANDLEABLE;

    if (emulate_pop(ctxt, &cs) != X86EMUL_CONTINUE)
        return X86EMUL_UNHANDLEABLE;

    if (!ctxt->ops->read_segment(ctxt, cs, &ctxt->src1_val, NULL))
        return X86EMUL_UNHANDLEABLE;

    ctxt->eip = eip;
    ctxt->regs->cs = cs;

    return X86EMUL_CONTINUE;
}

int handle_far_return(struct x86_emulate_ctxt *ctxt) {
    unsigned long eip, cs;
    int rc;

    rc = emulate_pop(ctxt, &eip);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    rc = emulate_pop(ctxt, &cs);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    /* Check for privilege level violations and load segment descriptor */
    rc =ctxt->ops->ctxt->ops->set_segment(ctxt, CS_SELECTOR, cs);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    ctxt->eip = eip;

    return X86EMUL_CONTINUE;
}
